// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.LmdbUtil.E;
import static org.lwjgl.util.lmdb.LMDB.MDB_NOSYNC;
import static org.lwjgl.util.lmdb.LMDB.mdb_env_get_flags;

import java.io.File;
import java.lang.reflect.Field;

import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A transaction delta spilled under memory pressure is deleted with its transaction, so syncing it buys no durability.
 * With a force-synced repository every buffered statement would otherwise wait for an fsync.
 */
class LmdbOverflowStoreSyncTest {

	@TempDir
	File tempDir;

	@Test
	void overflowStoreOfForceSyncedRepositoryDoesNotSync() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setForceSync(true);
		LmdbStore store = new LmdbStore(new File(tempDir, "repository"), config);
		store.init();
		try {
			LmdbSailStore repository = store.getBackingStore();
			assertThat(hasEnvFlag(repository.valueStore(), MDB_NOSYNC)).isFalse();
			assertThat(hasEnvFlag(repository.getTripleStore(), MDB_NOSYNC)).isFalse();

			File overflowDir = new File(tempDir, "overflow");
			overflowDir.mkdirs();
			LmdbSailStore overflow = store.createOverflowStore(overflowDir, false);
			try {
				assertThat(hasEnvFlag(overflow.valueStore(), MDB_NOSYNC)).as("overflow value store").isTrue();
				assertThat(hasEnvFlag(overflow.getTripleStore(), MDB_NOSYNC)).as("overflow triple store").isTrue();
			} finally {
				overflow.close();
			}
			assertThat(config.getForceSync()).as("the repository keeps its own setting").isTrue();
		} finally {
			store.shutDown();
		}
	}

	private static boolean hasEnvFlag(Object store, int flag) throws Exception {
		Field envField = store.getClass().getDeclaredField("env");
		envField.setAccessible(true);
		long env = (long) envField.get(store);
		int[] flags = new int[1];
		E(mdb_env_get_flags(env, flags));
		return (flags[0] & flag) != 0;
	}
}
